            END IF;

            IF handled_row_count = batch_size THEN
                batch_size := batch_size + 5;
            END IF;
        END LOOP;

    ELSIF threshold < 18 THEN
        state := 'ENHANCED_PROCESS';
        FOR rec IN SELECT * FROM "Restaurant_Type" WHERE "ResTypeID" > arg6 - 20 LOOP
            handled_row_count := handled_row_count + 1;

